    /// Returns the format character as a `DcChar`, if known.
    #[must_use]
    pub const fn dc_char(&self) -> Option<DcChar> {
        match self {
            Self::Unknown => None,
            _ => if let Some(dc) = self.dc_id() {
                Some(DcChar::from_u128(dc))
            } else {
                None
            }
        }
    }

